{"cards": [{"node_code": "N_d15c0c7a243bf5c6", "definition": "研究蒸汽机车锅炉系统的结构、热力过程及制造工艺，涵盖炉膛、烟管、水室、汽包及附属受热面等部件的设计与性能分析。", "boundary": "本节点聚焦于产生蒸汽的热源设备。边界在于区分“锅炉”与“蒸汽机”（前者产汽，后者用汽做功）；若涉及锅炉与机车整体热效率耦合，侧重锅炉本体结构归本节点。不包含内燃机燃油箱或电力机车受电弓等非蒸汽动力部件。", "includes": ["蒸汽机车锅炉本体结构（炉膛、烟箱、水室）", "锅炉受热面、烟管及汽水分离装置", "锅炉制造工艺、材料选择及检修维护技术"], "excludes": ["蒸汽机（汽缸、活塞、配汽机构）技术", "煤水车及燃料装载系统（归入煤水车节点）", "非铁路用途的工业锅炉设计"], "sibling_distinctions": [{"other_code": "N_f5f94e4f77e04773", "rule": "区分依据为功能环节：锅炉部分负责将燃料化学能转化为蒸汽热能；蒸汽机部分负责将蒸汽热能转化为机械能。"}, {"other_code": "N_77834d8e1b41be86", "rule": "区分依据为对象属性：锅炉是机车本体上的固定受热设备；煤水车是机车后部独立的燃料与水源储存及供给车辆。"}], "cross_boundary_rule": "若内容涉及锅炉给水系统与机车整体水循环，若侧重锅炉内部汽水动力学归本节点；若侧重外部供水管路及水箱连接，可关联辅助装置或煤水车。"}, {"node_code": "N_f5f94e4f77e04773", "definition": "研究蒸汽机车将蒸汽热能转化为机械牵引力的核心机构，涵盖汽缸、活塞、连杆、十字头及配汽阀等部件的运动学与动力学。", "boundary": "本节点聚焦于蒸汽做功的机械转换机构。边界在于区分“蒸汽机”与“锅炉”（前者用汽，后者产汽）；若涉及配汽阀与锅炉压力的耦合控制，侧重机械动作归本节点。不包含电气控制或内燃机燃烧室。", "includes": ["汽缸、活塞及活塞杆的结构与密封技术", "连杆、十字头及曲轴的传动机构设计", "配汽阀（如Walschaerts机构）的工作原理与调节"], "excludes": ["锅炉本体及受热面结构（归入锅炉部分）", "机车走行部轮对及轴箱（归入走行部分）", "制动系统管路及阀类（归入制动装置）"], "sibling_distinctions": [{"other_code": "N_d15c0c7a243bf5c6", "rule": "区分依据为能量转换阶段：蒸汽机部分处理蒸汽膨胀做功的机械过程；锅炉部分处理燃料燃烧产生蒸汽的热力过程。"}, {"other_code": "N_f62ad866045e3528", "rule": "区分依据为运动传递层级：蒸汽机部分研究动力源（活塞-曲轴）；走行部分研究动力输出后的轮轨接触及转向架结构。"}], "cross_boundary_rule": "若内容涉及蒸汽机与走行部的耦合振动分析，若侧重曲轴箱及连杆受力归本节点；若侧重轮对冲击及轴箱磨损，可关联走行部分。"}, {"node_code": "N_6afedcd81aade700", "definition": "研究蒸汽机车各运动部件的润滑系统，涵盖润滑油路、油杯、油泵及自动给油装置的设计、构造与运用维护技术。", "boundary": "本节点专指蒸汽机车机械摩擦副的润滑。边界在于区分“给油”与“给水”（前者润滑机械，后者产生蒸汽）；若涉及润滑油与燃油的混合（如某些特殊设计），需视具体语境，通常蒸汽机车燃油仅用于锅炉燃烧，归入煤水车或锅炉。不包含电力机车电机润滑。", "includes": ["蒸汽机车连杆、十字头、轴箱等部位的润滑结构", "手动及自动给油装置（如油杯、油泵）原理", "润滑油路布置、油质管理及润滑故障诊断"], "excludes": ["锅炉给水系统及水质处理（归入锅炉部分或辅助装置）", "煤水车燃油储存及锅炉燃烧供油（归入煤水车节点）", "非蒸汽机车的液压或电气润滑系统"], "sibling_distinctions": [{"other_code": "N_d15c0c7a243bf5c6", "rule": "区分依据为介质与功能：给油装置处理润滑油以减小机械摩擦；锅炉部分处理水以产生蒸汽。"}, {"other_code": "N_77834d8e1b41be86", "rule": "区分依据为流体类型：给油装置涉及润滑油；煤水车节点涉及锅炉用水及燃料（煤/油）的储存与供给。"}], "cross_boundary_rule": "若内容涉及润滑系统与走行部轴承的耦合，若侧重润滑管路及供油机构归本节点；若侧重轴承结构及磨损机理，可关联走行部分。"}]}
